css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); display: grid; place-items: center; perspective: 500px; }
.loader .die { position: relative; width: 56%; height: 56%; border-radius: 18%; background: linear-gradient(135deg, #fff, color-mix(in srgb, var(--accent-2) 32%, #fff)); box-shadow: inset 0 0 calc(var(--loader-size) * .05) rgba(0, 0, 0, .12); animation: roll calc(var(--loader-speed) * 1.6) cubic-bezier(.7, 0, .3, 1) infinite; }
.loader .die span { position: absolute; width: 17%; height: 17%; border-radius: 50%; background: var(--accent); }
.loader .die span:nth-child(1) { top: 16%; left: 16%; }
.loader .die span:nth-child(2) { top: 16%; right: 16%; }
.loader .die span:nth-child(3) { top: 41.5%; left: 41.5%; }
.loader .die span:nth-child(4) { bottom: 16%; left: 16%; }
.loader .die span:nth-child(5) { bottom: 16%; right: 16%; }
@keyframes roll { 0% { transform: rotateX(0deg) rotateY(0deg); } 50% { transform: rotateX(190deg) rotateY(90deg); } 100% { transform: rotateX(360deg) rotateY(180deg); } }
